def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Extend each colored marker along its row/column to the next marker
    # of the same color, filling only the intervening background.
    for r in range(h):
        for color in set(grid[r]) - {8}:
            positions = [c for c, v in enumerate(grid[r]) if v == color]
            for a, b in zip(positions, positions[1:]):
                if b - a <= 7:
                    for c in range(a + 1, b):
                        if grid[r][c] == 8:
                            out[r][c] = 2

    for c in range(w):
        for color in {grid[r][c] for r in range(h)} - {8}:
            positions = [r for r in range(h) if grid[r][c] == color]
            for a, b in zip(positions, positions[1:]):
                if b - a <= 7:
                    for r in range(a + 1, b):
                        if grid[r][c] == 8:
                            out[r][c] = 2

    return out
